            new Quote { Id = "https://uk.wikiquote.org/wiki/Панас_Мирний", Text = "Голод, лихий побратим убожества, — перший ворог ледарства.", Author = "Панас Мирний" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Панас_Мирний", Text = "Козак сам собі повинен знайти долю.", Author = "Панас Мирний" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Панас_Мирний", Text = "Мова — жива схованка людського духу, його багата скарбниця, в яку народ складає і своє давнє життя, і свої сподіванки, розум, досвід, почування.", Author = "Панас Мирний" },
