            new Quote { Id = "https://uk.wikiquote.org/wiki/Панас_Мирний", Text = "І скрізь вороги — і ворогів немає, бо люди пониділи: ніхто не хоче прямо мірятись силою!", Author = "Панас Мирний" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Панас_Мирний", Text = "Немає єдності — чорт має й волі!", Author = "Панас Мирний" },
